2-6fec2d0831ea","7ec573a1-ecdc-424b-a2e3-79436d38892b","802e42c1-206d-4ca4-b866-6e9b7e99ba5e","80cc827b-2e45-459b-a4ce-0fb1df243476","82c2d740-8690-4904-9673-9f01e181c8af","84d8fb7e-c48f-42b3-9632-1992ddcc59af","84f2aa8a-d721-48e3-965e-c7ce819f36ba","860fd7a5-6b79-46e2-b53d-92ecb434222e","862bb256-daca-4a40-aba2-8c0cb42305c3","8816b6ea-215d-4148-96e9-bcec22a1061e","8a73df7a-eda0-4779-98a3-5ef2fb7ffa22","9599a0fa-812a-4170-9bde-01a2090f78af","96c86844-380d-4bcd-8687-151a4f63be24","96ccf168-1290-4666-b63d-f1d602e490a1","974d06a9-799d-46af-85c6-91ee8e45d2d7","976e69b2-84f6-4383-a382-9c77a8394e13","9bc62d80-13e7-45ef-9260-685a7a90e8fa","9f553b32-1ea9-4f64-8d87-1fee372779bd","9f689c13-3770-4d09-ba36-a3ebdd049d74","a4b309a2-42dd-4e82-9dd9-e869a7d5eda2","a59a21c9-5ae8-4d10-8dbc-857737557e05","a67d4967-a19f-4fdb-9dab-fc6d663d5cb8","a77e43bf-7a5f-4a9c-852a-45e4b974997e","a86c903f-f014-4715-bceb-51d4b04f496f","ac457b3e-cede-4b4d-b7d9-12edab33696e","ae680158-ac65-4a13-99b3-45cdb3227931","afff4c86-e109-47b5-be91-449c23da0dd1","b1572973-ba78-4ff9-8a70-e912624f00bc","b4a490a0-5b90-436e-933f-fffdb378adfa","b5c207f9-0f29-4e77-ae95-351234d6c9f6","b8b0b942-b9a4-45f5-bd67-4e6c0024d3f6","bcc87c60-788a-477d-906f-08ab1892165c","bcededa1-3977-4736-9e33-9400eef5fb60","c7075628-67ae-448f-8874-3c90bc23be13","ccfbe1c0-292c-45bd-a11b-8084d5339918","cd6553cc-e9ca-4840-90fb-fecf3ee91c0b","d1e169bc-fd46-4869-8f8d-3ef3360ae2f0","d26fc973-8341-4661-a853-9384aa2e9fd5","d2c55de4-9573-4be2-9ac7-6d36c549aac3","d5ff7084-7ff1-41c6-9e83-741e78b6b699","d653e106-f68c-423d-80d7-a6cb02b08ec9","da732bf1-a923-4b8c-8247-053772af096d","e2bf4be4-8044-48e3-9f47-0e7d7c186d5c","e3133f5f-db89-42c2-af0a-3179e26eadf4","e3e85d37-d9ca-43da-9bd0-d6f48344976a","f060ff5f-5b9c-4389-b4ec-c78040e48eaf","f982799b-3d77-4f25-be9d-c641293506ff","fa360636-6a73-47e4-b013-289da324b871","faa43ba2-ffc2-4265-a687-235fcb597764","fb9d08d7-6c84-412a-a05b-c75ffe7e1510","fbcd515f-af4b-4f92-a0b5-a945860cb8bd","fe9f1b05-651a-4c2a-b3d3-471dfc06c376"]$party_release$::jsonb);

DO $$
DECLARE
    local_person_id CONSTANT UUID := '910cbcb1-6891-4fc0-8e7f-95a554318d8c';
    stable_external_id CONSTANT TEXT := 'cec-historical-person-33ac9d9656f5a063';
    target_person_id UUID;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM people WHERE id = local_person_id) THEN
        SELECT id INTO STRICT target_person_id
        FROM people
        WHERE external_id = stable_external_id;

        UPDATE _party_release_matches
        SET person_id = target_person_id,
            evidence_json = replace(evidence_json::TEXT, local_person_id::TEXT, target_person_id::TEXT)::JSONB
        WHERE person_id = local_person_id;

        UPDATE _party_release_sources
        SET source_payload = replace(source_payload::TEXT, local_person_id::TEXT, target_person_id::TEXT)::JSONB
        WHERE source_payload::TEXT LIKE '%' || local_person_id::TEXT || '%';

        UPDATE _party_release_claims
        SET claim_json = replace(claim_json::TEXT, local_person_id::TEXT, target_person_id::TEXT)::JSONB
        WHERE claim_json::TEXT LIKE '%' || local_person_id::TEXT || '%';

        DELETE FROM _party_release_required_people WHERE id = local_person_id;
        INSERT INTO _party_release_required_people (id) VALUES (target_person_id);
    END IF;
END
$$;

DO $$
DECLARE
    missing_people INTEGER;
    missing_races INTEGER;
BEGIN
    IF (SELECT COUNT(*) FROM _party_release_sources) <> 105
       OR (SELECT COUNT(*) FROM _party_release_people) <> 52
       OR (SELECT COUNT(*) FROM _party_release_matches) <> 110
       OR (SELECT COUNT(*) FROM _party_release_claims WHERE claim_type = 'candidacy') <> 105
       OR (SELECT COUNT(*) FROM _party_release_claims WHERE claim_type IN ('education', 'experience', 'platform')) <> 124
       OR (SELECT COUNT(*) FROM _party_release_candidates) <> 105
       OR (SELECT COUNT(*) FROM _party_release_required_people) <> 58 THEN
        RAISE EXCEPTION 'Reviewed party candidate release payload count drift';
    END IF;

    IF EXISTS (
        SELECT 1 FROM (VALUES ('education', 39), ('experience', 48), ('platform', 37)) expected_profile(claim_type, expected_count)
        WHERE (SELECT COUNT(*) FROM _party_release_claims claim WHERE claim.claim_type = expected_profile.claim_type) <> expected_profile.expected_count
    ) THEN
        RAISE EXCEPTION 'Reviewed party candidate profile claim count drift';
    END IF;

    SELECT COUNT(*) INTO missing_people
    FROM _party_release_required_people required
    WHERE NOT EXISTS (SELECT 1 FROM people person WHERE person.id = required.id);
    IF missing_people > 0 THEN
        RAISE EXCEPTION 'Reviewed party candidate release is missing % prerequisite people', missing_people;
    END IF;

    SELECT COUNT(*) INTO missing_races
    FROM _party_release_races required
    WHERE NOT EXISTS (SELECT 1 FROM races race WHERE race.id = required.id AND race.is_public = TRUE);
    IF missing_races > 0 THEN
        RAISE EXCEPTION 'Reviewed party candidate release is missing % public prerequisite races', missing_races;
    END IF;

    IF EXISTS (SELECT 1 FROM people existing JOIN _party_release_people incoming ON existing.id = incoming.id WHERE existing.external_id IS DISTINCT FROM incoming.external_id)
       OR EXISTS (SELECT 1 FROM people existing JOIN _party_release_people incoming ON existing.external_id = incoming.external_id WHERE existing.id <> incoming.id) THEN
        RAISE EXCEPTION 'Reviewed party candidate new-person identifier conflict';
    END IF;

    IF EXISTS (SELECT 1 FROM source_people existing JOIN _party_release_sources incoming ON existing.id = incoming.id WHERE existing.source_person_key <> incoming.source_person_key)
       OR EXISTS (SELECT 1 FROM source_people existing JOIN _party_release_sources incoming ON existing.source_person_key = incoming.source_person_key WHERE existing.id <> incoming.id) THEN
        RAISE EXCEPTION 'Reviewed party candidate source identifier conflict';
    END IF;

    IF EXISTS (SELECT 1 FROM person_identity_matches existing JOIN _party_release_matches incoming ON existing.source_person_id = incoming.source_person_id AND existing.person_id = incoming.person_id WHERE existing.id <> incoming.id) THEN
        RAISE EXCEPTION 'Reviewed party candidate identity-match identifier conflict';
    END IF;

    IF EXISTS (SELECT 1 FROM person_claims existing JOIN _party_release_claims incoming ON existing.claim_key = incoming.claim_key WHERE existing.id <> incoming.id) THEN
        RAISE EXCEPTION 'Reviewed party candidate claim identifier conflict';
    END IF;

    IF EXISTS (SELECT 1 FROM candidates existing JOIN _party_release_candidates incoming ON existing.external_id = incoming.external_id WHERE existing.id <> incoming.id)
       OR EXISTS (SELECT 1 FROM candidates existing JOIN _party_release_candidates incoming ON existing.person_id = incoming.person_id AND existing.race_id = incoming.race_id WHERE existing.id <> incoming.id) THEN
        RAISE EXCEPTION 'Reviewed party candidate identifier conflict';
    END IF;
END
$$;

INSERT INTO people (id, name, alias, party, position, election_year, district, source_url, is_public, created_at, updated_at, external_id, gender, education, experience)
SELECT id, name, alias, party, position, election_year, district, source_url, is_public, created_at, updated_at, external_id, gender, education, experience FROM _party_release_people
ON CONFLICT (id) DO NOTHING;

