INSERT INTO candidates (id, person_id, race_id, party, candidate_no, registration_status, source_name, source_url, is_public, created_at, updated_at, external_id, vote_count, vote_rate, is_elected, is_incumbent, candidacy_status, election_result, status_updated_at)
SELECT id, person_id, race_id, party, candidate_no, registration_status, source_name, source_url, is_public, created_at, updated_at, external_id, vote_count, vote_rate, is_elected, is_incumbent, candidacy_status, election_result, status_updated_at FROM _party_release_candidates
ON CONFLICT (id) DO UPDATE SET
    person_id = EXCLUDED.person_id,
    race_id = EXCLUDED.race_id,
    party = EXCLUDED.party,
    candidate_no = EXCLUDED.candidate_no,
    registration_status = EXCLUDED.registration_status,
    source_name = EXCLUDED.source_name,
    source_url = EXCLUDED.source_url,
    is_public = EXCLUDED.is_public,
    updated_at = EXCLUDED.updated_at,
    vote_count = EXCLUDED.vote_count,
    vote_rate = EXCLUDED.vote_rate,
    is_elected = EXCLUDED.is_elected,
    is_incumbent = EXCLUDED.is_incumbent,
    candidacy_status = EXCLUDED.candidacy_status,
    election_result = EXCLUDED.election_result,
    status_updated_at = EXCLUDED.status_updated_at;

UPDATE people
SET is_public = TRUE
WHERE id IN (SELECT person_id FROM _party_release_candidates);

DO $$
BEGIN
    IF (SELECT COUNT(*) FROM candidates candidate JOIN _party_release_candidates release ON release.id = candidate.id
        WHERE candidate.is_public = TRUE AND candidate.candidacy_status = 'party_nominee'
          AND candidate.registration_status = 'unknown' AND candidate.election_result = 'pending') <> 105 THEN
        RAISE EXCEPTION 'Reviewed party candidate final candidate verification failed';
    END IF;

    IF (SELECT COUNT(*) FROM source_people source JOIN _party_release_sources release ON release.id = source.id WHERE source.is_public = TRUE) <> 105
       OR (SELECT COUNT(*) FROM source_people source JOIN _party_release_sources release ON release.id = source.id WHERE source.is_public = FALSE) <> 0 THEN
        RAISE EXCEPTION 'Reviewed party candidate final source visibility verification failed';
    END IF;

    IF EXISTS (
        SELECT 1 FROM _party_release_sources source
        WHERE source.is_public = FALSE
          AND EXISTS (SELECT 1 FROM candidates candidate WHERE candidate.external_id = source.source_person_key)
    ) THEN
        RAISE EXCEPTION 'Rejected party candidate source still has a candidate row';
    END IF;
END
$$;

COMMIT;
